mapper.update:
UPDATE task_run
SET lease_expires_at = #{leaseExpiresAt}
WHERE id = #{id}

mapper.select:
SELECT COUNT(1)
FROM task_run r
         JOIN task t ON t.id = r.task_id
WHERE t.project_id = #{projectId}
  AND r.executor = #{executor}
  AND r.status = 'RUNNING'
  AND r.lease_expires_at IS NOT NULL
  AND r.lease_expires_at > #{now}
